import {chromium} from 'playwright';
import {mkdir,readFile,writeFile} from 'node:fs/promises';
const root='docs/qa/global-visual-lab/fern-native-sprite-bake-20261023/',out='public/assets/visual-lab/holly-fern-lod-20261023';await mkdir(out,{recursive:true});
const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage();for(const prefix of ['fern-day-','fern-night-','shadow-solar-']){const inputs=await Promise.all(Array.from({length:8},(_,i)=>readFile(root+prefix+i+'.png').then(b=>'data:image/png;base64,'+b.toString('base64'))));const data=await page.evaluate(async inputs=>{const images=await Promise.all(inputs.map(src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src;})));const c=document.createElement('canvas');c.width=2048;c.height=256;const ctx=c.getContext('2d');images.forEach((im,i)=>ctx.drawImage(im,i*256,0,256,256));return c.toDataURL().split(',')[1];},inputs);await writeFile(out+'/'+prefix.slice(0,-1)+'.png',Buffer.from(data,'base64'));}}finally{await browser.close();}
